slides=[]
for m in re.finditer(r'## Slide (\d+) — (.*?)\n(.*?)(?=\n## |\Z)',s,re.S):
 n=int(m[1]);title=m[2];body=m[3]
 points=[]
 for label,txt in re.findall(r'- \*\*(.*?):\*\* (.*)',body):
  label={'Scenario and objective':'Scenario + objective','Information and units':'Information needed','Evidence and interpretation':'Possible evidence'}.get(label,label)
  points.append(label+' — '+txt)
 slide={'number':n,'title':f'Project {n:02d}\n{title}','role':'single assigned project detailed brief','intent':'Explain the physical project and defensible decisions, preserving scaffolded Core scope.','key_points':points,'layout':{'composition':layout.get(n,'Approved sample composition retained.'),'intent':'Use one labelled physical diagram as principal learning object; keep five content groups legible. Vary arrangement while matching the samples.'},'visual_elements':{'main_visual':visuals.get(n,'Approved sample image retained.')},'constraints':['Render all five content groups in concise readable English; preserve meaning and units. Use regular body weight and clear headings.','No outer frame, decorative border, timing, watermark, logo or page numbers. Project identifier is content, permitted in title.','No numerical graph or invented computed evidence. Conceptual scientific diagrams only. No code or model derivations.','Do not turn examples into compulsory checklist, imply students choose projects, or claim data/starter files already supplied.','Keep title readable in two or three lines if needed. No tiny text, overflow or overlaps.']}
 if n in (1,3):slide['sample_approved']=True
 slides.append(slide)
